class Email {
  private constructor(readonly value: string) {}   // enforced at compile time
  static from(text: string): Email {
    const value = text.trim().toLowerCase();
    if (!value.includes('@')) throw new RangeError('invalid address');
    return new Email(value);
  }
  static fromUserId(id: number): Email {
    return new Email(`user${id}@example.com`);
  }
}
